Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include<cstdio>
#include<cstring>
#include<algorithm>
using namespace std;

const int MAXN=15;
const int MAXM=100005;
const int INF=(int)1e9;
const int dx[4]={0,0,-1,1};
const int dy[4]={1,-1,0,0};

char mp[MAXN][MAXN], demand[MAXN][MAXN];
int n, limit, sx, sy, S, T, total;
int id[MAXN][MAXN], distZ[MAXN][MAXN], used[MAXN][MAXN];
int que[MAXM], level[MAXN*MAXN*2+5];
int head[MAXN*MAXN*2+5], ecnt=1;
struct Edge { int to, nxt, cap; } e[MAXM];
int distCell[MAXN][MAXN];
struct Point { int x, y; } qp[MAXM];

inline bool ok(int x, int y) {
    if (x < 0 || y < 0 || x >= n || y >= n || used[x][y] || mp[x][y] < '0' || mp[x][y] > '9') return 0;
    return 1;
}

void addEdge(int u, int v, int c) {
    e[++ecnt].to = v; e[ecnt].cap = c; e[ecnt].nxt = head[u]; head[u] = ecnt;
    e[++ecnt].to = u; e[ecnt].cap = 0; e[ecnt].nxt = head[v]; head[v] = ecnt;
}

void bfsZ() {
    int l = 1, r = 0;
    memset(distZ, 60, sizeof(distZ));
    distZ[sx][sy] = 0;
    qp[++r].x = sx; qp[r].y = sy;
    used[sx][sy] = 1;
    for (; l <= r; ++l) {
        int ax = qp[l].x, ay = qp[l].y;
        for (int k = 0; k < 4; ++k) {
            int nx = ax + dx[k], ny = ay + dy[k];
            if (ok(nx, ny)) {
                distZ[nx][ny] = distZ[ax][ay] + 1;
                used[nx][ny] = 1;
                qp[++r].x = nx; qp[r].y = ny;
            }
        }
    }
}

void findLinks(int tx, int ty, int node) {
    int l = 1, r = 0;
    memset(used, 0, sizeof(used));
    memset(distCell, 60, sizeof(distCell));
    used[tx][ty] = 1;
    distCell[tx][ty] = 0;
    qp[++r].x = tx; qp[r].y = ty;
    for (; l <= r; ++l) {
        int ax = qp[l].x, ay = qp[l].y;
        for (int k = 0; k < 4; ++k) {
            int nx = ax + dx[k], ny = ay + dy[k];
            if (ok(nx, ny)) {
                distCell[nx][ny] = distCell[ax][ay] + 1;
                used[nx][ny] = 1;
                if (distCell[nx][ny] < distZ[nx][ny]) {
                    qp[++r].x = nx; qp[r].y = ny;
                }
            }
        }
    }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (distCell[i][j] <= limit && demand[i][j] > '0' && demand[i][j] <= '9' && distCell[i][j] <= distZ[i][j])
                addEdge(node, id[i][j] + total, INF);
}

bool bfsLevel() {
    memset(level, -1, sizeof(level));
    int l = 1, r = 1;
    level[S] = 0;
    que[1] = S;
    while (l <= r) {
        int u = que[l++];
        for (int i = head[u]; i; i = e[i].nxt) {
            int v = e[i].to;
            if (e[i].cap > 0 && level[v] == -1) {
                level[v] = level[u] + 1;
                que[++r] = v;
            }
        }
    }
    return level[T] != -1;
}

int send(int u, int flow) {
    if (u == T) return flow;
    int got = 0;
    for (int i = head[u]; i && flow; i = e[i].nxt) {
        int v = e[i].to;
        if (e[i].cap > 0 && level[v] == level[u] + 1) {
            int ret = send(v, min(e[i].cap, flow));
            if (ret) {
                e[i].cap -= ret;
                e[i ^ 1].cap += ret;
                flow -= ret;
                got += ret;
            }
        }
    }
    if (!got) level[u] = INF;
    return got;
}

int maxFlow() {
    int ans = 0;
    while (bfsLevel()) {
        int f;
        while ((f = send(S, INF))) ans += f;
    }
    return ans;
}

int main() {
    scanf("%d%d", &n, &limit);
    for (int i = 0; i < n; ++i) scanf("%s", mp[i]);
    for (int i = 0; i < n; ++i) scanf("%s", demand[i]);

    for (sx = 0; sx < n; ++sx) {
        for (sy = 0; sy < n; ++sy)
            if (mp[sx][sy] == 'Z') break;
        if (sy != n) break;
    }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) id[i][j] = ++total;

    S = 2 * total + 1;
    T = S + 1;

    bfsZ();

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (mp[i][j] > '0' && mp[i][j] <= '9') {
                addEdge(S, id[i][j], mp[i][j] - '0');
                findLinks(i, j, id[i][j]);
            }

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            if (demand[i][j] > '0' && demand[i][j] <= '9')
                addEdge(id[i][j] + total, T, demand[i][j] - '0');

    printf("%d\n", maxFlow());
    return 0;
}
